// ITIL 4 Foundation questions. Original wording, written for Cloudlingo; not official exam questions.

addQuestions('itil-1', [
  { t: 'mc', q: 'In ITIL 4, what is service management?',
    o: ['A set of specialized organizational capabilities for enabling value for customers in the form of services', 'A tool for logging, tracking and reporting IT tickets raised by users', 'A formal contract between a service provider and a customer about services', 'The team that runs and maintains the organization’s data center equipment'], a: 0,
    e: 'Service management is about the organization’s capabilities that turn resources into value for customers through services, not a single tool or team.' },
  { t: 'mc', q: 'In ITIL 4, value is created how?',
    o: ['Together, by the service provider and the service consumer (co-creation)', 'By the service provider alone, which then hands value to the consumer', 'By the customer paying the agreed price for the service', 'By the supplier delivering hardware and software on time'], a: 0,
    e: 'Value is co-created: the consumer is an active part of creating value, not just a receiver of it.' },
  { t: 'mc', q: 'Which service consumer role defines the requirements for a service and takes responsibility for the outcomes?',
    o: ['Customer', 'User', 'Sponsor', 'Supplier'], a: 0,
    e: 'The customer defines requirements and owns the outcomes. The user uses the service, and the sponsor authorizes the budget.' },
  { t: 'mc', q: 'Which service consumer role authorizes the budget for service consumption?',
    o: ['Sponsor', 'Customer', 'User', 'Service owner'], a: 0,
    e: 'The sponsor approves the money. One person can hold more than one role, for example customer and sponsor.' },
  { t: 'mc', q: 'Which service consumer role actually uses the services?',
    o: ['User', 'Sponsor', 'Customer', 'Service provider'], a: 0,
    e: 'Users are the people who use the service day to day.' },
  { t: 'mc', q: 'What is an outcome?',
    o: ['A result for a stakeholder that is enabled by one or more outputs', 'A tangible deliverable of an activity', 'The money paid for a service', 'A possible event that could cause harm'], a: 0,
    e: 'An output is what an activity produces, such as a report. An outcome is the result the stakeholder cares about, such as a better decision made with that report.' },
  { t: 'mc', q: 'A team produces a monthly sales report. In ITIL terms, the report itself is:',
    o: ['An output', 'An outcome', 'A utility', 'A warranty'], a: 0,
    e: 'The report is a deliverable, so it is an output. What managers achieve with it is the outcome.' },
  { t: 'mc', q: 'What is utility?',
    o: ['The functionality a product or service offers to meet a particular need: what it does', 'The assurance that a service will meet agreed requirements: how it performs', 'The total cost of a service', 'A record of a service’s configuration'], a: 0,
    e: 'Utility means fit for purpose. Warranty means fit for use: available, secure, with enough capacity and continuity.' },
  { t: 'mc', q: 'An online banking service is available 99.9% of the time and is secure. Which aspect of the service does this describe?',
    o: ['Warranty', 'Utility', 'Output', 'Sponsorship'], a: 0,
    e: 'Availability, security, capacity and continuity are about warranty: whether the service works as agreed.' },
  { t: 'fill', q: 'A service is fit for purpose when it has enough ___.',
    o: ['utility', 'warranty', 'capacity', 'governance'], a: 0,
    e: 'Fit for purpose comes from utility; fit for use comes from warranty. A service needs both to create value.' },
  { t: 'mc', q: 'What is a service offering made of?',
    o: ['Goods, access to resources, and service actions', 'Only software licenses', 'Incidents, problems and changes', 'Customers, users and sponsors'], a: 0,
    e: 'A service offering can include goods (ownership passes to the consumer), access to resources (ownership stays with the provider) and service actions (things done for the consumer).' },
  { t: 'mc', q: 'In a service offering, a mobile phone given to the consumer to keep is an example of:',
    o: ['Goods', 'Access to resources', 'A service action', 'A service level'], a: 0,
    e: 'With goods, ownership moves to the consumer, who then takes responsibility for using them.' },
  { t: 'mc', q: 'Network access that stays owned by the provider, which the consumer can use under agreed terms, is an example of:',
    o: ['Access to resources', 'Goods', 'A service action', 'An outcome'], a: 0,
    e: 'With access to resources, ownership is not transferred; the consumer may use the resource under agreed conditions.' },
  { t: 'mc', q: 'Which THREE activities make up a service relationship?',
    o: ['Service provision, service consumption, and service relationship management', 'Plan, build, and run the services that customers use', 'Incident management, problem management, and change management', 'Service design, service transition, and service operation'], a: 0,
    e: 'A service relationship is the cooperation between provider and consumer: providing, consuming, and managing the relationship together.' },
  { t: 'mc', q: 'A cloud service means a company no longer pays for its own server room. In ITIL terms, this is:',
    o: ['A cost removed from the consumer', 'A cost imposed on the consumer', 'A risk imposed on the consumer', 'A warranty requirement'], a: 0,
    e: 'Services can remove costs (like running a server room) and impose costs (like subscription fees). Both are weighed when judging value.' },
  { t: 'mc', q: 'Which is a risk IMPOSED on a consumer by using a new service?',
    o: ['Disruption while moving to the new service', 'Lower hardware costs', 'Faster access to information', 'Fewer staff needed for maintenance'], a: 0,
    e: 'A new service can remove risks, such as hardware failure, but also impose some, such as disruption during the switch or depending on the provider.' },
  { t: 'mc', q: 'What is a service?',
    o: ['A means of enabling value co-creation by facilitating outcomes customers want, without the customer having to manage specific costs and risks', 'Any piece of hardware or software that an organization sells or leases to a customer under contract', 'A team of people who answer phone calls and emails from users and log every request', 'A document that lists every IT asset an organization owns, with its owner, location and cost'], a: 0,
    e: 'A service helps the customer get outcomes while the provider manages specific costs and risks for them.' },
  { t: 'mc', q: 'What is a product in ITIL 4?',
    o: ['A configuration of an organization’s resources designed to offer value for a consumer', 'Only a physical item that can be packaged and shipped to a customer', 'An agreement between a provider and a customer about service levels', 'A user’s request for information, advice or access to a service'], a: 0,
    e: 'Products are built from resources and are the basis for service offerings aimed at different consumer groups.' },
  { t: 'tf', q: 'In ITIL 4, the same person can be the customer, the user and the sponsor of a service.', a: true,
    e: 'Roles are about responsibilities, not people. Someone buying a personal phone plan is customer, user and sponsor at once.' },
  { t: 'match', q: 'Match each term to its meaning.',
    pairs: [['Output', 'A deliverable of an activity'], ['Outcome', 'A result a stakeholder wants'], ['Utility', 'What a service does'], ['Warranty', 'How well a service performs']],
    e: 'Outputs enable outcomes; utility and warranty together make a service valuable.' },
  { t: 'mc', q: 'Which TWO are part of warranty?\n1. Availability\n2. Security\n3. The features the service offers\n4. The price of the service',
    o: ['1 and 2', '2 and 3', '3 and 4', '1 and 4'], a: 0,
    e: 'Warranty covers availability, capacity, security and continuity. Features are utility; price is a cost.' },
  { t: 'mc', q: 'Who are stakeholders in value co-creation?',
    o: ['Consumers, providers, employees, partners, investors and society', 'Only the customers who pay for the services', 'Only the IT department that delivers the services', 'Only the suppliers that provide goods and services'], a: 0,
    e: 'Many groups get or give value from a service, and a good provider considers all of them.' },
]);

addQuestions('itil-2', [
  { t: 'mc', q: 'Which TWO are ITIL 4 guiding principles?\n1. Focus on value\n2. Keep it simple and practical\n3. Plan everything in full before starting\n4. Avoid automation',
    o: ['1 and 2', '2 and 3', '3 and 4', '1 and 4'], a: 0,
    e: 'The seven principles: focus on value; start where you are; progress iteratively with feedback; collaborate and promote visibility; think and work holistically; keep it simple and practical; optimize and automate.' },
  { t: 'mc', q: 'Which guiding principle says everything the organization does should link back to value for stakeholders?',
    o: ['Focus on value', 'Start where you are', 'Optimize and automate', 'Think and work holistically'], a: 0,
    e: 'Focus on value means knowing who the consumer is and what they value, and keeping that in mind in every step.' },
  { t: 'mc', q: 'Before replacing a process, a team measures how the current one works and keeps what is useful. Which guiding principle is this?',
    o: ['Start where you are', 'Keep it simple and practical', 'Collaborate and promote visibility', 'Focus on value'], a: 0,
    e: 'Start where you are: don’t throw everything away. Observe the current state directly and reuse what works.' },
  { t: 'mc', q: 'A large improvement is split into small pieces that are delivered and reviewed one by one. Which guiding principle is this?',
    o: ['Progress iteratively with feedback', 'Optimize and automate', 'Start where you are', 'Think and work holistically'], a: 0,
    e: 'Work in small, manageable iterations and use feedback before, during and after each one to adjust.' },
  { t: 'mc', q: 'Which guiding principle encourages involving the right people and making work and progress visible to everyone?',
    o: ['Collaborate and promote visibility', 'Keep it simple and practical', 'Focus on value', 'Optimize and automate'], a: 0,
    e: 'Working together across boundaries and making work visible builds trust and leads to better decisions.' },
  { t: 'mc', q: 'Which guiding principle reminds you that no service or component stands alone, so you should consider the whole system?',
    o: ['Think and work holistically', 'Start where you are', 'Progress iteratively with feedback', 'Keep it simple and practical'], a: 0,
    e: 'Results suffer when parts are optimized in isolation. Consider all four dimensions and how components work together.' },
  { t: 'mc', q: 'A process has steps nobody can explain the value of. Which guiding principle suggests removing them?',
    o: ['Keep it simple and practical', 'Start where you are', 'Collaborate and promote visibility', 'Think and work holistically'], a: 0,
    e: 'Keep it simple and practical: use the minimum number of steps that achieves the objective, and drop anything that adds no value.' },
  { t: 'mc', q: 'According to the "optimize and automate" principle, what should you do BEFORE automating a process?',
    o: ['Optimize it first, so you don’t automate waste', 'Automate it straight away to save time', 'Buy the most powerful tool available', 'Remove all human checks'], a: 0,
    e: 'Simplify and optimize first, then automate. Automating a poor process only makes the waste happen faster.' },
  { t: 'tf', q: 'The ITIL guiding principles should each be applied on their own, one at a time.', a: false,
    e: 'The principles interact and should be considered together; which ones matter most depends on the situation.' },
  { t: 'mc', q: 'Which statement about the guiding principles is TRUE?',
    o: ['They are universal and enduring, and apply to almost any initiative and relationship', 'They apply only to IT departments', 'They replace the need for practices', 'They are mandatory rules that must be followed word for word'], a: 0,
    e: 'The guiding principles are recommendations that can guide an organization in all circumstances, whatever its goals or structure.' },
  { t: 'mc', q: 'A team wants feedback from users after each small release so it can change course early. Which guiding principle does this reflect?',
    o: ['Progress iteratively with feedback', 'Keep it simple and practical', 'Optimize and automate', 'Start where you are'], a: 0,
    e: 'Feedback loops after each iteration let you learn and adjust before investing more.' },
  { t: 'mc', q: 'Under "focus on value", what should you understand FIRST?',
    o: ['Who the service consumer is and what they value', 'Which tool to buy for the service desk', 'How much the improvement project will cost', 'Which team in the organization is the largest'], a: 0,
    e: 'Value is judged by the consumer, so start by knowing who they are and what matters to them.' },
  { t: 'mc', q: 'Under "start where you are", how should the current state be assessed?',
    o: ['By observing it directly, as well as using reports and data', 'Only from management reports', 'By assuming everything needs to be replaced', 'By copying another organization'], a: 0,
    e: 'Reports can be biased or out of date. Going to see the work directly gives a truer picture.' },
  { t: 'fill', q: 'Automation should come after a process has been simplified, following the principle "optimize and ___".',
    o: ['automate', 'outsource', 'escalate', 'document'], a: 0,
    e: 'Optimize and automate: make work as effective as possible, then use technology for repetitive tasks so people can focus on complex work.' },
  { t: 'mc', q: 'Which guiding principle warns that working in silos leads to poor results?',
    o: ['Collaborate and promote visibility', 'Focus on value', 'Optimize and automate', 'Progress iteratively with feedback'], a: 0,
    e: 'Silos hide information and slow decisions. Collaboration and visibility break them down.' },
  { t: 'mc', q: 'A team builds a solution that handles every possible exception, so it takes a year to deliver. Which principle did they ignore?',
    o: ['Keep it simple and practical', 'Start where you are', 'Think and work holistically', 'Collaborate and promote visibility'], a: 0,
    e: 'Trying to cover every exception makes solutions complex and slow. Design for the common case and handle exceptions sensibly.' },
  { t: 'match', q: 'Match each guiding principle to its key idea.',
    pairs: [['Start where you are', 'Reuse what already works'], ['Keep it simple and practical', 'Remove steps that add no value'], ['Think and work holistically', 'Consider the whole system'], ['Optimize and automate', 'Improve before you automate']],
    e: 'Each principle gives a different lens; together they guide decisions in any situation.' },
  { t: 'tf', q: 'Under "progress iteratively with feedback", each iteration should still be big enough to deliver everything at once.', a: false,
    e: 'Iterations should be small and manageable; even a large initiative is broken into smaller pieces that each deliver something.' },
  { t: 'mc', q: 'How many guiding principles does ITIL 4 describe?',
    o: ['Seven', 'Four', 'Five', 'Fifteen'], a: 0,
    e: 'There are seven guiding principles. ITIL 4 also has four dimensions, five SVS components and six value chain activities.' },
  { t: 'mc', q: 'A manager wants to make work-in-progress visible on a shared board so bottlenecks are easy to see. Which principle is this?',
    o: ['Collaborate and promote visibility', 'Optimize and automate', 'Start where you are', 'Keep it simple and practical'], a: 0,
    e: 'Visible work helps everyone see priorities and bottlenecks and supports better decisions.' },
  { t: 'mc', q: 'Which principle includes the idea that customer experience and user experience are part of value?',
    o: ['Focus on value', 'Think and work holistically', 'Keep it simple and practical', 'Start where you are'], a: 0,
    e: 'Focus on value includes how it feels to use a service, not just what it does.' },
]);

addQuestions('itil-3', [
  { t: 'mc', q: 'Which TWO are among the four dimensions of service management?\n1. Organizations and people\n2. Value streams and processes\n3. Incidents and problems\n4. Budgets and contracts',
    o: ['1 and 2', '2 and 3', '3 and 4', '1 and 4'], a: 0,
    e: 'The four dimensions: organizations and people; information and technology; partners and suppliers; value streams and processes.' },
  { t: 'mc', q: 'Which dimension covers roles, responsibilities, culture and the skills of staff?',
    o: ['Organizations and people', 'Information and technology', 'Partners and suppliers', 'Value streams and processes'], a: 0,
    e: 'Organizations and people is about structure, culture, roles, competencies and leadership.' },
  { t: 'mc', q: 'Which dimension covers the knowledge needed to manage services and the tools that support them?',
    o: ['Information and technology', 'Organizations and people', 'Partners and suppliers', 'Value streams and processes'], a: 0,
    e: 'Information and technology includes the information managed by services, the technology used, and how they relate.' },
  { t: 'mc', q: 'A company decides which work to outsource and which to keep in-house. Which dimension is this?',
    o: ['Partners and suppliers', 'Organizations and people', 'Information and technology', 'Value streams and processes'], a: 0,
    e: 'Partners and suppliers covers relationships with other organizations involved in designing, delivering and supporting services.' },
  { t: 'mc', q: 'Which dimension describes how the parts of an organization work together to create value through activities and workflows?',
    o: ['Value streams and processes', 'Partners and suppliers', 'Information and technology', 'Organizations and people'], a: 0,
    e: 'Value streams and processes define the activities, workflows and controls that create products and services.' },
  { t: 'mc', q: 'What do the external factors that affect all four dimensions (PESTLE) stand for?',
    o: ['Political, economic, social, technological, legal and environmental', 'People, events, services, technology, licenses and errors', 'Plan, engage, support, test, launch and evaluate', 'Partners, employees, suppliers, teams, leaders and executives'], a: 0,
    e: 'PESTLE factors are outside the organization’s control but constrain or influence all four dimensions.' },
  { t: 'mc', q: 'What are the inputs to the ITIL service value system (SVS)?',
    o: ['Opportunity and demand', 'Incidents and problems', 'Budget and staff', 'Hardware and software'], a: 0,
    e: 'Opportunity and demand come in; value for the organization and its stakeholders comes out.' },
  { t: 'mc', q: 'What is the output of the service value system?',
    o: ['Value', 'Opportunity', 'Demand', 'Change requests'], a: 0,
    e: 'The SVS turns opportunity and demand into value through its components and activities.' },
  { t: 'mc', q: 'Which TWO are components of the service value system?\n1. Governance\n2. Continual improvement\n3. Service desk\n4. Incident management',
    o: ['1 and 2', '2 and 3', '3 and 4', '1 and 4'], a: 0,
    e: 'SVS components: guiding principles, governance, service value chain, practices and continual improvement. Service desk and incident management are practices, which form one component.' },
  { t: 'mc', q: 'In the SVS, what is the purpose of governance?',
    o: ['To direct and control the organization', 'To restore normal service quickly', 'To log every user request', 'To build and test software'], a: 0,
    e: 'Governance evaluates, directs and monitors the organization’s activities so they stay aligned with its strategy.' },
  { t: 'mc', q: 'How many activities does the service value chain have?',
    o: ['Six', 'Four', 'Seven', 'Five'], a: 0,
    e: 'Plan; improve; engage; design and transition; obtain/build; deliver and support.' },
  { t: 'mc', q: 'Which value chain activity provides understanding of stakeholder needs, transparency and good relationships with all stakeholders?',
    o: ['Engage', 'Plan', 'Improve', 'Obtain/build'], a: 0,
    e: 'Engage is the main point of contact with stakeholders, inside and outside the organization.' },
  { t: 'mc', q: 'Which value chain activity ensures that service components are available when and where they are needed and meet agreed specifications?',
    o: ['Obtain/build', 'Deliver and support', 'Design and transition', 'Plan'], a: 0,
    e: 'Obtain/build gets or creates the components, such as hardware, software and contracts.' },
  { t: 'mc', q: 'Which value chain activity ensures services are delivered and supported according to agreed specifications and stakeholder expectations?',
    o: ['Deliver and support', 'Engage', 'Obtain/build', 'Improve'], a: 0,
    e: 'Deliver and support runs the live services day to day.' },
  { t: 'mc', q: 'Which value chain activity ensures products and services continually meet expectations for quality, costs and time to market?',
    o: ['Design and transition', 'Plan', 'Engage', 'Deliver and support'], a: 0,
    e: 'Design and transition designs new or changed services and moves them into the live environment.' },
  { t: 'mc', q: 'Which value chain activity creates a shared understanding of the vision, current status and improvement direction?',
    o: ['Plan', 'Improve', 'Engage', 'Design and transition'], a: 0,
    e: 'Plan sets direction for all four dimensions and all products and services.' },
  { t: 'mc', q: 'Which value chain activity ensures continual improvement of products, services and practices across all activities?',
    o: ['Improve', 'Plan', 'Deliver and support', 'Obtain/build'], a: 0,
    e: 'Improve works across the whole value chain and all four dimensions.' },
  { t: 'mc', q: 'What is a value stream?',
    o: ['A series of steps an organization takes to create and deliver products and services to consumers', 'A list of all IT assets with their owners, costs and locations', 'A contract with a supplier that sets out what they will deliver', 'A report on how well services met their agreed service levels'], a: 0,
    e: 'Value streams combine value chain activities and practices in a specific order for a specific scenario, such as fixing a user’s issue.' },
  { t: 'tf', q: 'The service value chain activities must always be performed in the same fixed order.', a: false,
    e: 'Activities can be combined in many sequences, called value streams, depending on the situation.' },
  { t: 'match', q: 'Match each service value chain activity to its focus.',
    pairs: [['Engage', 'Relationships with stakeholders'], ['Plan', 'Shared vision and direction'], ['Obtain/build', 'Getting service components ready'], ['Deliver and support', 'Running live services']],
    e: 'Together with improve and design and transition, these six activities turn demand into value.' },
]);

addQuestions('itil-4', [
  { t: 'mc', q: 'What is the purpose of the information security management practice?',
    o: ['To protect the information needed by the organization to conduct its business', 'To restore normal service as quickly as possible', 'To set clear business-based targets for service levels', 'To move new software into live environments'], a: 0,
    e: 'It covers confidentiality, integrity and availability of information, plus authentication and non-repudiation.' },
  { t: 'mc', q: 'Which practice establishes and nurtures links between the organization and its stakeholders at strategic and tactical levels?',
    o: ['Relationship management', 'Supplier management', 'Service desk', 'Service level management'], a: 0,
    e: 'Relationship management identifies, analyzes, monitors and continually improves relationships with stakeholders.' },
  { t: 'mc', q: 'What is the purpose of the supplier management practice?',
    o: ['To ensure suppliers and their performance are managed appropriately to support seamless products and services', 'To manage relationships with customers at strategic and tactical levels', 'To plan and manage the full lifecycle of all IT assets the organization owns', 'To make new and changed services and features available for use'], a: 0,
    e: 'Supplier management includes creating closer relationships with key suppliers to find and realize new value.' },
  { t: 'mc', q: 'Which practice plans and manages the full lifecycle of all IT assets to maximize value, control costs and manage risks?',
    o: ['IT asset management', 'Service configuration management', 'Deployment management', 'Release management'], a: 0,
    e: 'IT asset management tracks assets from purchase to disposal, supporting decisions about buying, reusing and retiring them.' },
  { t: 'mc', q: 'Which practice systematically observes services and components, and records and reports selected changes of state identified as events?',
    o: ['Monitoring and event management', 'Incident management', 'Problem management', 'Service request management'], a: 0,
    e: 'It decides which events matter and makes sure the right response happens, for example raising an incident.' },
  { t: 'mc', q: 'What is the purpose of the release management practice?',
    o: ['To make new and changed services and features available for use', 'To move hardware and software into live environments', 'To authorize changes', 'To fix the causes of incidents'], a: 0,
    e: 'Release management decides when features become available to users; deployment management moves the components.' },
  { t: 'mc', q: 'Which practice moves new or changed hardware, software, documentation and processes to live environments?',
    o: ['Deployment management', 'Release management', 'Change enablement', 'IT asset management'], a: 0,
    e: 'Deployment can happen separately from release: code can be deployed but kept switched off until it is released.' },
  { t: 'mc', q: 'Which practice ensures accurate and reliable information about the configuration of services and the CIs that support them is available when needed?',
    o: ['Service configuration management', 'IT asset management', 'Monitoring and event management', 'Information security management'], a: 0,
    e: 'It records configuration items and how they relate, which helps with changes, incidents and problems.' },
  { t: 'mc', q: 'What is a configuration item (CI)?',
    o: ['Any component that needs to be managed in order to deliver an IT service', 'Any unplanned interruption to a service or reduction in its quality', 'A request from a user for information, advice or a standard change', 'A cause, or potential cause, of one or more incidents'], a: 0,
    e: 'CIs can be hardware, software, documents, services or even people, if they need managing to deliver the service.' },
  { t: 'mc', q: 'What is an IT asset?',
    o: ['Any financially valuable component that can contribute to delivering an IT product or service', 'Any change of state that has significance for the management of a service', 'A record of a past incident and how it was resolved', 'A document that describes the agreed service levels for a customer'], a: 0,
    e: 'IT assets have financial value, such as servers, laptops and software licenses.' },
  { t: 'mc', q: 'What is an event?',
    o: ['Any change of state that has significance for the management of a service or other configuration item', 'An unplanned interruption to a service or a reduction in its quality', 'A request from a user for something standard, such as a new laptop', 'A change that has been assessed, approved and added to the schedule'], a: 0,
    e: 'Events are often detected by monitoring tools. Some are just information; others need action.' },
  { t: 'mc', q: 'What is a change?',
    o: ['The addition, modification or removal of anything that could have a direct or indirect effect on services', 'An unplanned reduction in the quality of a service that users notice', 'A cause, or potential cause, of one or more incidents', 'A user’s request for a standard action, such as a password reset'], a: 0,
    e: 'Change enablement manages these so that risks are assessed and changes are authorized.' },
  { t: 'mc', q: 'What is an incident?',
    o: ['An unplanned interruption to a service, or reduction in its quality', 'A cause, or potential cause, of one or more incidents', 'A planned change to a service', 'A user asking how to use a feature'], a: 0,
    e: 'Incidents are about restoring service quickly; their causes are handled by problem management.' },
  { t: 'mc', q: 'What is a problem?',
    o: ['A cause, or potential cause, of one or more incidents', 'An unplanned interruption to a service', 'A request for a standard service', 'A change that failed'], a: 0,
    e: 'A problem is about the cause. A known error is a problem that has been analyzed but not resolved.' },
  { t: 'mc', q: 'What is a known error?',
    o: ['A problem that has been analyzed but has not been resolved', 'An incident that keeps coming back', 'An error in a change request form', 'A bug that has already been fixed'], a: 0,
    e: 'Known errors often have workarounds documented while a permanent fix is pending.' },
  { t: 'mc', q: 'What is the purpose of the incident management practice?',
    o: ['To minimize the negative impact of incidents by restoring normal service operation as quickly as possible', 'To reduce the likelihood of incidents by finding and removing their causes', 'To assess and authorize changes so that they succeed', 'To handle user requests for standard services in an agreed way'], a: 0,
    e: 'Incident management restores service; problem management deals with causes.' },
  { t: 'mc', q: 'What is the purpose of the problem management practice?',
    o: ['To reduce the likelihood and impact of incidents by identifying actual and potential causes and managing workarounds and known errors', 'To minimize the impact of incidents by restoring normal service operation as quickly as possible', 'To capture demand for incident resolution and service requests, as the single point of contact for users', 'To set clear business-based targets for service levels and ensure delivery is monitored against them'], a: 0,
    e: 'Problem management works on root causes so incidents happen less often or have less impact.' },
  { t: 'mc', q: 'What is the purpose of the change enablement practice?',
    o: ['To maximize the number of successful changes by ensuring risks are assessed, changes are authorized and the change schedule is managed', 'To make new and changed services and features available for use, as planned and agreed with stakeholders', 'To move new or changed hardware, software, documentation and processes into live environments', 'To minimize the impact of failures by restoring normal service operation as quickly as possible'], a: 0,
    e: 'Change enablement balances the need for change with protecting live services from harmful changes.' },
  { t: 'mc', q: 'What is the purpose of the service request management practice?',
    o: ['To support the agreed quality of a service by handling all predefined, user-initiated service requests effectively and user-friendly', 'To minimize the negative impact of outages by restoring normal service operation as quickly as possible', 'To maximize successful changes by assessing risks, authorizing changes and managing the change schedule', 'To ensure suppliers and their performance are managed to support seamless products and services'], a: 0,
    e: 'Service requests are normal parts of service delivery, such as access requests or ordering equipment, not failures.' },
  { t: 'mc', q: 'What is the purpose of the service desk practice?',
    o: ['To capture demand for incident resolution and service requests, and be the entry point and single point of contact for all users', 'To reduce the likelihood of incidents by diagnosing the root causes of problems and managing workarounds', 'To maximize the number of successful changes by assessing risks and authorizing each change', 'To negotiate supplier contracts and make sure suppliers deliver what was agreed'], a: 0,
    e: 'The service desk is the main point of contact between the service provider and its users.' },
  { t: 'mc', q: 'What is the purpose of the service level management practice?',
    o: ['To set clear business-based targets for service levels, and ensure delivery is properly assessed, monitored and managed against them', 'To plan and manage the full lifecycle of all IT assets to maximize value, control costs and manage risks', 'To handle every predefined, user-initiated service request in an effective and user-friendly way', 'To make new and changed services available for use and move releases into production'], a: 0,
    e: 'Service level management agrees targets with customers and checks whether they are met.' },
  { t: 'mc', q: 'What is the purpose of the continual improvement practice?',
    o: ['To align the organization’s practices and services with changing business needs through ongoing improvement', 'To minimize the impact of incidents by restoring normal service operation as quickly as possible', 'To capture and log all user requests and route them to the right team', 'To manage software licenses and other IT assets across their lifecycle'], a: 0,
    e: 'Continual improvement applies at every level of the organization, from strategy to individual tasks.' },
  { t: 'match', q: 'Match each practice to its purpose.',
    pairs: [['Incident management', 'Restore normal service quickly'], ['Problem management', 'Reduce incidents by tackling causes'], ['Change enablement', 'Assess risk and authorize changes'], ['Service desk', 'Single point of contact for users']],
    e: 'These four practices are often confused; focus on the key verb of each purpose.' },
  { t: 'tf', q: 'Release management and deployment management are the same practice in ITIL 4.', a: false,
    e: 'Deployment moves components into live environments; release makes features available to users. The two can happen at different times.' },
  { t: 'fill', q: 'Any component that needs to be managed in order to deliver an IT service is called a configuration ___.',
    o: ['item', 'record', 'event', 'asset'], a: 0,
    e: 'Configuration items (CIs) are tracked by service configuration management, often in a CMDB.' },
  { t: 'mc', q: 'A monitoring tool reports that a disk is 95% full. In ITIL terms, this notification is:',
    o: ['An event', 'An incident', 'A problem', 'A change'], a: 0,
    e: 'It is a change of state worth knowing about. It may lead to an incident if the disk fills and the service is affected.' },
]);

addQuestions('itil-5', [
  { t: 'mc', q: 'What is the FIRST step of the continual improvement model?',
    o: ['What is the vision?', 'Where are we now?', 'Take action', 'Did we get there?'], a: 0,
    e: 'The model: what is the vision; where are we now; where do we want to be; how do we get there; take action; did we get there; how do we keep the momentum going.' },
  { t: 'mc', q: 'In the continual improvement model, which step assesses the current state with baseline measurements?',
    o: ['Where are we now?', 'What is the vision?', 'How do we get there?', 'How do we keep the momentum going?'], a: 0,
    e: 'You need an objective baseline to know whether improvements actually worked.' },
  { t: 'mc', q: 'Which continual improvement step checks whether the improvement achieved its objectives?',
    o: ['Did we get there?', 'Where do we want to be?', 'Take action', 'What is the vision?'], a: 0,
    e: 'Compare results against the targets set earlier. If they weren’t met, decide what to do next.' },
  { t: 'mc', q: 'What is a continual improvement register (CIR) used for?',
    o: ['To track and manage improvement ideas from identification to final action', 'To record every incident and how quickly it was resolved', 'To list all changes that have been approved for implementation', 'To store supplier contracts and their renewal dates'], a: 0,
    e: 'A CIR keeps improvement ideas in one place so they can be prioritized and followed up.' },
  { t: 'tf', q: 'Continual improvement is the responsibility of a dedicated team only, not of everyone in the organization.', a: false,
    e: 'Everyone contributes to continual improvement, even if a dedicated team leads and supports it.' },
  { t: 'mc', q: 'Which type of change is low-risk, pre-authorized and well understood, so it can be done without extra approval?',
    o: ['Standard change', 'Normal change', 'Emergency change', 'Major change'], a: 0,
    e: 'Standard changes are fully documented and pre-authorized; they are often initiated as service requests.' },
  { t: 'mc', q: 'Which type of change must be scheduled, assessed and authorized following a process, with the authority depending on the type of change?',
    o: ['Normal change', 'Standard change', 'Emergency change', 'Pre-approved change'], a: 0,
    e: 'Normal changes go through assessment and authorization by the appropriate change authority.' },
  { t: 'mc', q: 'A security patch must be applied immediately to stop an active attack. Which type of change is this?',
    o: ['Emergency change', 'Standard change', 'Normal change', 'Service request'], a: 0,
    e: 'Emergency changes must be done as soon as possible. They are still assessed and authorized, but through a faster route.' },
  { t: 'mc', q: 'Who assesses and authorizes a normal change?',
    o: ['The change authority assigned to that type of change', 'The service desk agent who logs it', 'Any user affected by it', 'Always the CEO'], a: 0,
    e: 'Different changes can have different change authorities. In agile and DevOps teams, authority is often decentralized to peers.' },
  { t: 'mc', q: 'What is the change schedule used for?',
    o: ['To plan changes, help communication, avoid conflicts and assign resources', 'To record user complaints and how they were handled', 'To list known errors and their documented workarounds', 'To store the agreed targets for each service level'], a: 0,
    e: 'The change schedule shows planned and past changes, which also helps incident and problem management.' },
  { t: 'mc', q: 'How should incidents be prioritized?',
    o: ['By their impact on the business and their urgency', 'In the order they were logged', 'By who reported them', 'By how easy they are to fix'], a: 0,
    e: 'Agreed classifications based on impact and urgency make sure the most important incidents are handled first.' },
  { t: 'mc', q: 'What is swarming in incident management?',
    o: ['Many stakeholders working together on an incident until it becomes clear who is best placed to continue', 'Escalating every incident straight to management so it gets attention quickly', 'Automatically closing duplicate incidents that describe the same failure', 'Assigning incidents to teams strictly in the order in which they were logged'], a: 0,
    e: 'Swarming is useful for complex incidents where the right expert isn’t obvious at first.' },
  { t: 'mc', q: 'How are simple incidents often resolved quickly?',
    o: ['By the service desk using scripts or by users through self-help', 'By always opening a problem record to find the root cause', 'By raising an emergency change to fix the service', 'By waiting for the next release to include a fix'], a: 0,
    e: 'Many incidents can be fixed at first contact or by users themselves with good self-help tools.' },
  { t: 'tf', q: 'Incidents should be logged and managed so they are resolved in times that meet consumer and customer expectations.', a: true,
    e: 'Target resolution times should be agreed, documented and communicated so expectations are realistic.' },
  { t: 'mc', q: 'Users can’t reach the email service. The team restores it by restarting a server, without yet knowing why it failed. What has been done?',
    o: ['The incident was resolved; the cause is a matter for problem management', 'The problem was resolved, because the service is working again', 'A known error was fixed permanently by the restart', 'A standard change was implemented to restore the service'], a: 0,
    e: 'Restoring service resolves the incident. Finding and removing the cause is problem management.' },
  { t: 'mc', q: 'What are the three phases of problem management?',
    o: ['Problem identification, problem control, and error control', 'Detection, diagnosis, and closure', 'Plan, do, and check', 'Logging, escalation, and resolution'], a: 0,
    e: 'Identification finds problems, control analyzes them and documents workarounds, and error control manages known errors and possible fixes.' },
  { t: 'mc', q: 'What is a workaround?',
    o: ['A solution that reduces or eliminates the impact of an incident or problem when a full resolution is not yet available', 'A permanent fix that removes the underlying cause of a problem so it can’t happen again', 'A pre-approved, low-risk change that can be implemented without further authorization', 'A way for users to skip the service desk and contact the support teams directly'], a: 0,
    e: 'Workarounds keep services usable while the underlying cause is still being fixed. They should be documented.' },
  { t: 'mc', q: 'Which problem management phase analyzes problems, documents workarounds and identifies known errors?',
    o: ['Problem control', 'Problem identification', 'Error control', 'Incident control'], a: 0,
    e: 'Problem control focuses on analysis and workarounds; error control manages known errors and their fixes.' },
  { t: 'mc', q: 'How do problem management and change enablement work together?',
    o: ['A permanent fix for a problem is often implemented through change enablement', 'Problem management approves all changes before they are implemented', 'Change enablement logs and investigates all problems', 'They never interact, because they cover separate activities'], a: 0,
    e: 'Fixing a known error usually means changing something, so the fix goes through change enablement.' },
  { t: 'tf', q: 'Problem management can identify problems before any incident has happened, for example by analyzing trends.', a: true,
    e: 'Proactive problem identification uses trend analysis, supplier information and testing to find potential causes early.' },
  { t: 'mc', q: 'Which is an example of a service request?',
    o: ['A user asks for access to a shared folder', 'A web server crashes', 'A database is slow for everyone', 'Customers can’t log in'], a: 0,
    e: 'Service requests are normal, expected parts of service delivery. Failures and degradations are incidents.' },
  { t: 'mc', q: 'Which statement about service requests is correct?',
    o: ['They should be standardized and automated as much as possible, with predefined workflows', 'They always need approval from a change authority', 'They are a kind of incident', 'Each one should be handled in a completely new way'], a: 0,
    e: 'Standardized workflows and automation make requests fast and consistent; some need no extra approval.' },
  { t: 'mc', q: 'Which skill is especially important for service desk staff?',
    o: ['Empathy and understanding of the user’s situation', 'Writing complex code', 'Designing data centers', 'Negotiating supplier contracts'], a: 0,
    e: 'Service desks need good communication, empathy and an understanding of the wider business, not only technical skills.' },
  { t: 'mc', q: 'Staff in several countries work together as one service desk using shared tools. What is this called?',
    o: ['A virtual service desk', 'A local service desk', 'A problem desk', 'A change advisory board'], a: 0,
    e: 'A virtual service desk lets agents in different places work as one team with shared tools and records.' },
  { t: 'mc', q: 'Which TWO are channels a service desk can use?\n1. Phone and live chat\n2. Self-service portals\n3. Root cause analysis\n4. Change authorization',
    o: ['1 and 2', '2 and 3', '3 and 4', '1 and 4'], a: 0,
    e: 'Service desks offer many channels, such as phone, chat, email, portals and walk-in desks.' },
  { t: 'mc', q: 'What is a service level agreement (SLA)?',
    o: ['A documented agreement between a service provider and a customer that identifies services and expected service levels', 'A record of all configuration items that support a service and the relationships between them', 'A list of all changes that have been assessed, approved and scheduled for implementation', 'An agreement between two suppliers that sets out how they will work together on a contract'], a: 0,
    e: 'Good SLAs are written in simple language and tied to outcomes the customer cares about.' },
  { t: 'mc', q: 'All SLA targets show green, but customers are unhappy. What is this called?',
    o: ['The watermelon SLA effect', 'Swarming', 'A known error', 'Service request backlog'], a: 0,
    e: 'Green outside, red inside: the metrics look fine but don’t reflect what customers actually experience.' },
  { t: 'mc', q: 'Besides metrics, what helps service level management understand how customers really feel about a service?',
    o: ['Customer engagement and feedback, such as surveys and regular conversations', 'Only system uptime reports from the monitoring tools', 'The number of changes made to the service each month', 'The size of the service desk team that supports it'], a: 0,
    e: 'Talking to customers and collecting feedback reveals issues that operational metrics miss.' },
  { t: 'fill', q: 'A documented agreement between a provider and a customer about expected service levels is called a service level ___.',
    o: ['agreement', 'requirement', 'register', 'record'], a: 0,
    e: 'SLAs set the targets that service level management monitors and reviews with the customer.' },
]);

